public class InternalFileDecryptorSetFileCryptoMetaDataTests {

  @Test
  public void initializesFileAadFromFileUniqueValue() throws Exception {
    byte[] fileUnique = new byte[] {1, 2, 3, 4};
    InternalFileDecryptor decryptor =
        new InternalFileDecryptor(FileDecryptionProperties.builder().build());

    decryptor.setFileCryptoMetaData(
        encryptionAlgorithm(aesGcm(fileUnique, null, false)), false, null);

    assertArrayEquals(fileUnique, readByteArrayField(decryptor, "fileAAD"));
  }

  @Test
  public void combinesConfiguredAadPrefixWithFileUniqueValue() throws Exception {
    byte[] aadPrefix = new byte[] {10, 11};
    byte[] fileUnique = new byte[] {20, 21, 22};
    Object metadata = aesGcm(fileUnique, null, true);

    InternalFileDecryptor decryptor =
        new InternalFileDecryptor(
            FileDecryptionProperties.builder().withAADPrefix(aadPrefix).build());

    decryptor.setFileCryptoMetaData(encryptionAlgorithm(metadata), false, null);

    byte[] expected = new byte[] {10, 11, 20, 21, 22};
    assertArrayEquals(expected, readByteArrayField(decryptor, "fileAAD"));
  }

