    byte[] fileUnique = new byte[] {1, 2};
    InternalFileDecryptor decryptor =
        new InternalFileDecryptor(FileDecryptionProperties.builder().build());

    assertThrows(
        ParquetCryptoRuntimeException.class,
        () ->
            decryptor.setFileCryptoMetaData(
                encryptionAlgorithm(aesGcm(fileUnique, null, true)), false, null));
  }

  @Test
  public void rejectsAadPrefixThatDiffersFromTheFilePrefix() {
    byte[] filePrefix = new byte[] {1, 2};
    byte[] configuredPrefix = new byte[] {3, 4};
    Object metadata = aesGcm(new byte[] {5}, filePrefix, false);

    InternalFileDecryptor decryptor =
        new InternalFileDecryptor(
            FileDecryptionProperties.builder().withAADPrefix(configuredPrefix).build());

    assertThrows(
        ParquetCryptoRuntimeException.class,
        () ->
            decryptor.setFileCryptoMetaData(
                encryptionAlgorithm(metadata), false, null));
  }

  @Test
  public void rejectsConfiguredPrefixWhenFileEncryptionDidNotUseOne() {
    Object metadata = aesGcm(new byte[] {7, 8}, null, false);
