                new EncryptionAlgorithm(), false, null));
  }

  @Test
  public void retrievesFooterKeyWhenEncryptedFooterRequiresIt() throws Exception {
    byte[] keyMetadata = new byte[] {30, 31};
    byte[] footerKey = new byte[] {40, 41, 42};
    AtomicInteger retrievalCount = new AtomicInteger();

    InternalFileDecryptor decryptor =
        new InternalFileDecryptor(
            FileDecryptionProperties.builder()
                .withKeyRetriever(
                    metadata -> {
                      retrievalCount.incrementAndGet();
                      assertArrayEquals(keyMetadata, metadata);
                      return footerKey;
                    })
                .build());

    decryptor.setFileCryptoMetaData(
        encryptionAlgorithm(aesGcm(new byte[] {50}, null, false)),
        true,
        keyMetadata);

    assertEquals(1, retrievalCount.get());
    assertArrayEquals(footerKey, readByteArrayField(decryptor, "footerKey"));
  }

  @Test
  public void validatesMetadataOnReuseAndRejectsDifferentFooterMetadata() {
    byte[] keyMetadata = new byte[] {60, 61};
    EncryptionAlgorithm algorithm =
        encryptionAlgorithm(aesGcm(new byte[] {62}, null, false));
    InternalFileDecryptor decryptor =
        new InternalFileDecryptor(FileDecryptionProperties.builder().build());

    decryptor.setFileCryptoMetaData(algorithm, false, keyMetadata);

    assertThrows(
        ParquetCryptoRuntimeException.class,
        () ->
            decryptor.setFileCryptoMetaData(
                algorithm, false, new byte[] {63, 64}));
  }

  @Test
  public void validatesMetadataOnReuseAndRejectsDifferentFooterEncryption() {
    EncryptionAlgorithm algorithm =
        encryptionAlgorithm(aesGcm(new byte[] {70}, null, false));
    InternalFileDecryptor decryptor =
        new InternalFileDecryptor(FileDecryptionProperties.builder().build());

    decryptor.setFileCryptoMetaData(algorithm, false, null);

    assertThrows(
        ParquetCryptoRuntimeException.class,
        () -> decryptor.setFileCryptoMetaData(algorithm, true, null));
  }

  @Test
  public void successfulReuseLeavesFileAadUnchanged() throws Exception {
    byte[] fileUnique = new byte[] {80, 81, 82};
    EncryptionAlgorithm algorithm =
        encryptionAlgorithm(aesGcm(fileUnique, null, false));
    InternalFileDecryptor decryptor =
        new InternalFileDecryptor(FileDecryptionProperties.builder().build());

    decryptor.setFileCryptoMetaData(algorithm, false, null);
    byte[] aadAfterFirstCall = readByteArrayField(decryptor, "fileAAD");

    decryptor.setFileCryptoMetaData(algorithm, false, null);

    assertArrayEquals(aadAfterFirstCall, readByteArrayField(decryptor, "fileAAD"));
  }

  private static Object aesGcm(
      byte[] fileUnique, byte[] aadPrefix, boolean supplyAadPrefix) {
    try {
      Method setter = EncryptionAlgorithm.class.getMethod("setAES_GCM_V1", findAesGcmType());
      Class<?> metadataType = setter.getParameterTypes()[0];
      Constructor<?> constructor = metadataType.getDeclaredConstructor();
      Object metadata = constructor.newInstance();

      invoke(metadata, "setAad_file_unique", fileUnique);
      if (aadPrefix != null) {
        invoke(metadata, "setAad_prefix", aadPrefix);
      }
      invoke(metadata, "setSupply_aad_prefix", supplyAadPrefix);
      return metadata;
    } catch (ReflectiveOperationException e) {
      throw new AssertionError("Unable to construct AES-GCM metadata", e);
    }
  }

  private static EncryptionAlgorithm encryptionAlgorithm(Object metadata) {
    try {
      EncryptionAlgorithm algorithm = new EncryptionAlgorithm();
      Method setter =
          EncryptionAlgorithm.class.getMethod("setAES_GCM_V1", metadata.getClass());
      setter.invoke(algorithm, metadata);
      return algorithm;
    } catch (ReflectiveOperationException e) {
      throw new AssertionError("Unable to configure encryption algorithm", e);
    }
  }

  private static Class<?> findAesGcmType() throws ReflectiveOperationException {
    for (Method method : EncryptionAlgorithm.class.getMethods()) {
      if (method.getName().equals("setAES_GCM_V1")
          && method.getParameterCount() == 1) {
        return method.getParameterTypes()[0];
      }
    }
    throw new NoSuchMethodException("setAES_GCM_V1");
  }

  private static void invoke(Object target, String methodName, Object argument)
      throws ReflectiveOperationException {
    Method method = target.getClass().getMethod(methodName, argument.getClass());
    method.invoke(target, argument);
  }

  private static byte[] readByteArrayField(Object target, String fieldName)
      throws Exception {
    Field field = target.getClass().getDeclaredField(fieldName);
    field.setAccessible(true);
    byte[] value = (byte[]) field.get(target);
    return value == null ? null : Arrays.copyOf(value, value.length);
  }
}

